//	handlers

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// List page: Before SQL query
function BeforeQueryList(&$strSQL, &$strWhereClause, &$strOrderBy, &$pageObject)
{

		if ($_SESSION["rol"] == 'Docente') {
    $strWhereClause = whereAdd($strWhereClause, "curso_id IN (SELECT id FROM cursos WHERE profesor_id = " . intval($_SESSION["profesor_id"]) . ")");
} elseif ($_SESSION["rol"] == 'Alumno') {
    $strWhereClause = whereAdd($strWhereClause, "estudiante_id = " . intval($_SESSION["estudiante_id"]));
}
;		
} // function BeforeQueryList

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record added
function BeforeAdd(&$values, &$message, $inline, &$pageObject)
{

		$est_id   = intval($values["estudiante_id"]);
$curso_id = intval($values["curso_id"]);

if ($est_id <= 0 || $curso_id <= 0) {
    $message = "Debe especificar el estudiante y la cátedra.";
    return false;
}

// 1. Evitar doble inscripción
$rsDup = DB::Query("SELECT id FROM inscripciones WHERE estudiante_id = " . $est_id . " AND curso_id = " . $curso_id . " LIMIT 1");
if ($rsDup->fetchAssoc()) {
    $message = "El estudiante ya se encuentra inscripto en esta cátedra.";
    return false;
}

// 2. Control estricto de cupo
$rsCupo = DB::Query("SELECT c.cupo, COUNT(i.id) AS inscriptos 
                     FROM cursos c 
                     LEFT JOIN inscripciones i ON i.curso_id = c.id 
                     WHERE c.id = " . $curso_id . " GROUP BY c.id, c.cupo");
if ($rowCupo = $rsCupo->fetchAssoc()) {
    if (intval($rowCupo["inscriptos"]) >= intval($rowCupo["cupo"])) {
        $message = "La cátedra ha alcanzado su cupo máximo de " . $rowCupo["cupo"] . " estudiantes.";
        return false;
    }
}

if (empty($values["fecha_inscripcion"])) {
    $values["fecha_inscripcion"] = date("Y-m-d H:i:s");
}

return true;
;		
} // function BeforeAdd

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record deleted
function BeforeDelete($where, &$deleted_values, &$message, &$pageObject)
{

		$insc_id = intval($deleted_values["id"]);

$rsNotas = DB::Query("SELECT COUNT(*) AS total FROM notas WHERE inscripcion_id = " . $insc_id);
$rN = $rsNotas->fetchAssoc();
if (intval($rN["total"]) > 0) {
    $message = "No es posible anular la inscripción porque el estudiante ya cuenta con calificaciones oficiales registradas en el acta.";
    return false;
}

return true;
;		
} // function BeforeDelete

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		



